\version "2.27.2"
% automatically converted by musicxml2ly from 43a-PianoStaff.xml
\pointAndClickOff

\header {
  texidoc = "A simple piano staff, i.e., two voices, each on a separate staff."
}
\layout {
  \context {
    \Staff
    printKeyCancellation = ##f
  }
  \context {
    \Score
    autoBeaming = ##f
  }
}
PartPOneVoiceOne = \relative f' {
  \clef "treble" \numericTimeSignature \time 4/4 \key c \major f1 }

PartPOneVoiceTwo = \relative b, {
  \clef "bass" \numericTimeSignature \time 4/4 \key c \major b1 }


% The score definition
\score {
  <<
    \new PianoStaff = "P1" <<
      \context Staff = "1" <<
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceOne" {
          \PartPOneVoiceOne
        }
      >>
      \context Staff = "2" <<
        \override Staff.BarLine.allow-span-bar = ##f
        \mergeDifferentlyDottedOn
        \mergeDifferentlyHeadedOn
        \context Voice = "PartPOneVoiceTwo" {
          \PartPOneVoiceTwo
        }
      >>
    >>
  >>
  \layout {}
  % To create MIDI output, uncomment the following line:
  % \midi { \tempo 4 = 100 }
}
